import asyncio
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("Utility Server")

@mcp.tool()
def calculate(expression: str) -> str:
    """Evaluate a mathematical expression safely."""
    try:
        allowed_names = {"abs": abs, "round": round, "min": min, "max": max, "sum": sum, "pow": pow}
        result = eval(expression, {"__builtins__": {}}, allowed_names)
        return f"Result: {result}"
    except Exception as e:
        return f"Error: {str(e)}"

@mcp.tool()
def convert_units(value: float, from_unit: str, to_unit: str) -> str:
    """Convert between units."""
    conversions = {
        ("km", "miles"): lambda x: x * 0.621371,
        ("celsius", "fahrenheit"): lambda x: (x * 9/5) + 32,
    }
    key = (from_unit.lower(), to_unit.lower())
    if key in conversions:
        return f"{value} {from_unit} = {conversions[key](value):.4f} {to_unit}"
    return "Error"

@mcp.tool()
def word_count(text: str) -> str:
    words = text.split()
    return f"Words: {len(words)}, Characters: {len(text)}"

@mcp.tool()
def get_timestamp() -> str:
    from datetime import datetime
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

async def main():
    tools = await mcp.list_tools()
    print("Available tools:")
    for t in tools:
        print(f"  - {t.name}: {t.description}")

    print("\nTesting tools:")
    r = await mcp.call_tool("calculate", {"expression": "2 + 2"})
    print(f"  calculate: {r[0][0].text}")

    r = await mcp.call_tool("convert_units", {"value": 100, "from_unit": "celsius", "to_unit": "fahrenheit"})
    print(f"  convert_units: {r[0][0].text}")

    r = await mcp.call_tool("word_count", {"text": "Hello world"})
    print(f"  word_count: {r[0][0].text}")

    r = await mcp.call_tool("get_timestamp", {})
    print(f"  get_timestamp: {r[0][0].text}")

asyncio.run(main())
EOF

